def transform(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # border segments: maximal runs >=2 of any non-bg color
    segs=[]
    for i in range(H):
        j=0
        while j<W:
            if g[i][j]!=bg:
                c=g[i][j]; j2=j
                while j2+1<W and g[i][j2+1]==c: j2+=1
                if j2>j: segs.append(('h',i,j,j2,c))
                j=j2+1
            else: j+=1
    for j in range(W):
        i=0
        while i<H:
            if g[i][j]!=bg:
                c=g[i][j]; i2=i
                while i2+1<H and g[i2+1][j]==c: i2+=1
                if i2>i: segs.append(('v',j,i,i2,c))
                i=i2+1
            else: i+=1
    bsegs=[s for s in segs if s[4]!=bg]
    bcolor=bsegs[0][4]
    bsegs=[s[:4] for s in bsegs]
    # marker color: isolated non-bg cells
    marker=None
    for i in range(H):
        for j in range(W):
            if g[i][j] not in (bg,bcolor): marker=g[i][j]
    vertical = bsegs[0][0]=='v'
    out=[r[:] for r in g]
    if vertical:
        # segs: (col, r0, r1)
        sA,sB=bsegs
        markers=[(i,j) for i in range(H) for j in range(W) if g[i][j]==marker]
        # block containing markers
        inA=lambda r: sA[1]<=r<=sA[2]
        mb, ob = (sA,sB) if any(inA(r) for r,_ in markers) else (sB,sA)
        for r,c in markers:
            bc=mb[0]; r0=mb[1]
            if bc<c: rng=range(bc+1,c)
            else: rng=range(c+1,bc)
            for j in rng: out[r][j]=marker
            out[r][c]=4
            k=r-r0
            orow=ob[1]+k; oc=ob[0]
            if oc==0: rng2=range(1,W)
            else: rng2=range(0,W-1)
            for j in rng2: out[orow][j]=marker
    else:
        sA,sB=bsegs  # ('h', row, c0, c1)
        markers=[(i,j) for i in range(H) for j in range(W) if g[i][j]==marker]
        inA=lambda c: sA[2]<=c<=sA[3]
        mb, ob = (sA,sB) if any(inA(c) for _,c in markers) else (sB,sA)
        for r,c in markers:
            br=mb[1]; c0=mb[2]
            if br<r: rng=range(br+1,r)
            else: rng=range(r+1,br)
            for i in rng: out[i][c]=marker
            out[r][c]=4
            k=c-c0
            ocol=ob[2]+k; orow=ob[1]
            if orow==0: rng2=range(1,H)
            else: rng2=range(0,H-1)
            for i in rng2: out[i][ocol]=marker
    return out

